class Stack:
    def __init__(self):
        self.data = []
    def push(self, v):
        self.data.append(v)
    def pop(self):
        return self.data.pop()
    def size(self):
        return len(self.data)
s = Stack()
s.push(1)
s.push(2)
print(s.size(), s.pop(), s.size())

